      en: "A masterpiece of 19th-century Lebanese architecture that served as the governmental seat of Emir Bashir Shihab II.",
      es: "Una obra maestra de la arquitectura libanesa del siglo XIX, que sirvió como sede del gobierno del emir Bashir Shihab II.",
      pt: "Uma obra-prima da arquitetura libanesa do século XIX, que serviu como sede do governo do emir Bashir Shihab II.",
      fr: "Un chef-d'œuvre de l'architecture libanaise du XIXe siècle, ayant servi de siège du gouvernement à l'émir Bachir Chehab II.",
